const lastPairs="In progress|চলছে\nCompleted|শেষ হয়েছে\nReopen stage|ধাপ আবার খুলুন\nsessions today|আজকের সেশন\ndifferent pages|আলাদা পৃষ্ঠা\ndifferent pages recorded|আলাদা পৃষ্ঠা পড়া হয়েছে\nbook pages|বইয়ের পৃষ্ঠা\npages today|আজ পড়া পৃষ্ঠা\nof daily goal|দৈনিক লক্ষ্যের\n. New revisions start at zero. Earlier reports are kept.|। নতুন রিভিশন শূন্য থেকে শুরু হয়। আগের প্রতিবেদন রাখা হয়।\n · repeated pages count once in this total.| · এই মোট হিসাবে একই পৃষ্ঠা একবারই ধরা হয়।\nCopy to|কপি করুন:\nLog my day|দিনের কাজ লিখুন\nStart with your first record.|প্রথম রেকর্ড দিয়ে শুরু করুন।\nYour first small step|আপনার প্রথম ছোট পদক্ষেপ\nper day|প্রতিদিন\nrecorded days|লেখা দিন\nPlanned|পরিকল্পনা\nActual|বাস্তব কাজ\nNot set|দেওয়া হয়নি\nNo data|কোনো তথ্য নেই\nBudget|বাজেট\nGoal|লক্ষ্য\nToday|আজ\nYesterday|গতকাল\nTomorrow|আগামীকাল\nReset|আবার শুরু করুন\nView|দেখুন\nHide|লুকান\nShow|দেখান\nDaily|প্রতিদিন\nWeekly|সাপ্তাহিক\nMonthly|মাসিক\nYearly|বার্ষিক\nto|থেকে\nfrom|থেকে\nUp to|সর্বোচ্চ\nSaved days|সংরক্ষিত দিন\nrecorded|লেখা হয়েছে\nClose book|বই বন্ধ করুন\nLearn more|আরও জানুন\nContinue|এগিয়ে যান";
const dictionary=Object.fromEntries((pairs+'\n'+extraPairs+'\n'+morePairs+'\n'+supplementaryPairs+'\n'+lastPairs).split('\n').map(line=>{const i=line.indexOf('|');return[line.slice(0,i),line.slice(i+1)]}));
const folded=Object.fromEntries(Object.entries(dictionary).map(([key,value])=>[key.trim().toLowerCase(),value.trim()]));
const escapeRegex=s=>Array.from(s,c=>'.*+?^${}()|[]'.includes(c)||c.charCodeAt(0)===92?String.fromCharCode(92)+c:c).join('');
const phrases=Object.keys(dictionary).map(key=>key.trim()).filter(key=>key&&/[a-z]/i.test(key)).sort((a,b)=>b.length-a.length);
const phrasePattern=new RegExp('(?<![A-Za-z])(?:'+phrases.map(escapeRegex).join('|')+')(?![A-Za-z])','gi');
let language='en';try{language=localStorage.getItem('progressdiary.language')==='bn'?'bn':'en'}catch{}
const protectedText=new Set();
window.ProgressDiaryLanguage={
get language(){return language},
get locale(){return language==='bn'?'bn-BD':'en-GB-u-nu-latn'},
protectData(value){const seen=new WeakSet();function visit(item){if(!item||typeof item!=='object'||seen.has(item))return;seen.add(item);for(const [key,child]of Object.entries(item)){if(['name','institution','department','note','topic','text','otherExpenseReason'].includes(key)&&typeof child==='string'&&child.trim())protectedText.add(child);else if(child&&typeof child==='object')visit(child)}}visit(value)},
protect(value){if(typeof value==='string'&&value)protectedText.add(value);return value},
set(value){language=value==='bn'?'bn':'en';try{localStorage.setItem('progressdiary.language',language)}catch{}document.documentElement.lang=language;window.dispatchEvent(new Event('progressdiary-language'));},
text(value){if(language!=='bn'||typeof value!=='string'||protectedText.has(value))return value;if(dictionary[value])return dictionary[value];const trimmed=value.trim();if(/^\d+h \d+m$/.test(trimmed))return trimmed.replace('h ',' ঘণ্টা ').replace('m',' মিনিট');if(folded[trimmed.toLowerCase()])return value.replace(trimmed,folded[trimmed.toLowerCase()]);return value.replace(phrasePattern,match=>dictionary[match]||folded[match.toLowerCase()]||match);},
props(type,props){if(!props||typeof type!=='string'||['script','style','canvas'].includes(type)||(props.lang&&['blockquote','p'].includes(type))||props['data-diary-user'])return props;const next={...props};if(type==='option'&&!('value'in next)&&typeof next.children==='string')next.value=next.children;function children(v){return typeof v==='string'?window.ProgressDiaryLanguage.text(v):Array.isArray(v)?v.map(children):v}next.children=children(next.children);for(const key of ['title','placeholder','aria-label','alt'])if(typeof next[key]==='string')next[key]=window.ProgressDiaryLanguage.text(next[key]);return next}
};
document.documentElement.lang=language;
for(const name of ['confirm','alert'])if(typeof window[name]==='function'){const original=window[name].bind(window);window[name]=message=>original(window.ProgressDiaryLanguage.text(message));}
